const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.1/projects/%7Bproject_id%7D/bid_packages',
  qs: {
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    view: 'SOME_STRING_VALUE',
    filter: 'SOME_STRING_VALUE',
    with_flags: 'SOME_ARRAY_VALUE',
    sort: 'SOME_STRING_VALUE',
    'filters[bid_due_date]': 'SOME_STRING_VALUE',
    'filters[status]': 'SOME_STRING_VALUE',
    'filters[created_at]': 'SOME_STRING_VALUE',
    'filters[has_bid_forms]': 'SOME_BOOLEAN_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.1/projects/%7Bproject_id%7D/bid_packages?page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&view=SOME_STRING_VALUE&filter=SOME_STRING_VALUE&with_flags=SOME_ARRAY_VALUE&sort=SOME_STRING_VALUE&filters%5Bbid_due_date%5D=SOME_STRING_VALUE&filters%5Bstatus%5D=SOME_STRING_VALUE&filters%5Bcreated_at%5D=SOME_STRING_VALUE&filters%5Bhas_bid_forms%5D=SOME_BOOLEAN_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
